// Parse the agent's JSON reply into an `output` object. If the reply is empty or invalid,
// fall back to a manual-review record instead of failing the run.
const p = $('Fetch Inventory and Lead Times (mock)').item.json;
const raw = String($json.output ?? '').trim();
let a = null;
try {
  const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
  if (s !== -1 && e > s) a = JSON.parse(raw.slice(s, e + 1));
} catch (err) { a = null; }
if (!a) a = { project_id: p.project_id, critical_shortage: false, shortages: [], summary: 'Automated forecast returned no usable result - manual review required.' };
if (!Array.isArray(a.shortages)) a.shortages = [];
a.critical_shortage = (a.critical_shortage === true || a.critical_shortage === 'true');
return { json: { output: a } };

// Mock purchase order creation (fictional) - stands in for a procurement system API
const a = $('Parse Agent Output').item.json.output;
const p = $('Fetch Inventory and Lead Times (mock)').item.json;
const lines = (a.shortages || []).map(s => `${s.order_qty} x ${s.material} (${s.urgency})`);
return { json: { po_id: 'PO-' + Math.floor(Math.random()*90000+10000), project_id: a.project_id, project: p.project, pm: p.pm, po_lines: lines.join('; '), summary: a.summary, created_at: new Date().toISOString() } };

